-- Specialised MCQ items (radiography_interpreter): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'در فیلم رادیوگرافی یک جوش محیطی، خطی تیره، پیوسته و مستقیم در مرکز عرض جوش و در امتداد ریشه دیده می‌شود. تفسیر صحیح چیست؟', '["عدم ذوب جانبی (IF) در دیواره پخ","ترک عرضی در فلز جوش","تخلخل کرمی در پاس ریشه","نفوذ ناقص ریشه (IP)"]'::jsonb, 3, 'SINGLE', null, 'IP به‌صورت خط تیرهٔ مستقیم و تیز در مرکز جوش (محل ریشه) دیده می‌شود؛ ظاهر IF خطی در لبهٔ جوش و موازی با دیواره پخ است.', 'API 1104 / ASNT – تفسیر فیلم'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 1, 'لکه‌های تیرهٔ گرد یا بیضی کوچک با لبهٔ صاف و پراکنده در جوش، نشانهٔ کدام عیب است؟', '["تخلخل گازی (Porosity)","سرباره کشیده (ESI)","ترک طولی","زیرگرفتگی (Undercut)"]'::jsonb, 0, 'SINGLE', null, 'حفره‌های گازی چگالی کم‌تر و پرتو بیشتری عبور می‌دهند و به‌صورت لکه‌های گرد تیره دیده می‌شوند.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'خطوط تیره، نامنظم و کشیده با لبه‌های ناصاف داخل جوش (گاهی موازی هم) معمولاً کدام عیب است؟', '["تخلخل کروی منفرد در ریشه","سرباره محبوس (Slag)","نفوذ بیش از حد ریشه (Excess)","ناهم‌ترازی لبه‌ها (High-Low)"]'::jsonb, 1, 'SINGLE', null, 'سرباره به‌صورت خطوط نامنظم و گاه دوخط موازی (Wagon tracks) در کنار پاس‌ها دیده می‌شود.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'خط تیرهٔ بسیار باریک، شکسته و تیز با جهت نامنظم در فیلم، نشانهٔ کدام عیب است؟', '["تخلخل خوشه‌ای (CP)","نفوذ ناقص ناشی از ناهم‌ترازی","ترک (Crack)","سوختگی ریشه (Burn-through)"]'::jsonb, 2, 'SINGLE', null, 'ترک‌ها خطوط تیز، باریک و اغلب شکسته‌اند و نیاز به دقت بالای تفسیر و تشخیص از خراشیدگی فیلم دارند.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'نقاط روشن (سفید) نامنظم و کوچک در ناحیهٔ جوش در فیلم ایجاد شده‌اند. محتمل‌ترین علت چیست؟', '["حفره‌های گازی ریز در فلز جوش","سرباره کم‌چگالی در پاس پرکننده","عدم ذوب جانبی در دیواره پخ","ناخالصی چگال مانند تنگستن (GTAW)"]'::jsonb, 3, 'SINGLE', null, 'مواد چگال‌تر از فولاد، پرتو بیشتری جذب می‌کنند و روی فیلم روشن دیده می‌شوند؛ مثل ذرات تنگستن.', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'اختلاف ناگهانی چگالی در دو طرف جوش به‌صورت خطی مستقیم در امتداد جوش، معمولاً نشانهٔ چیست؟', '["ناهم‌ترازی لبه‌ها (High-Low)","ترک طولی در فلز جوش","خوشهٔ تخلخل در پاس پرکننده","سرباره کشیده در پاس ریشه"]'::jsonb, 0, 'SINGLE', null, 'ضخامت مؤثر دو طرف جوش متفاوت است و تفاوت چگالی با مرز مستقیم دیده می‌شود.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 2, 'در لبهٔ گرده جوش، نوار تیرهٔ نامنظم با تغییر تدریجی چگالی دیده می‌شود. تفسیر چیست؟', '["نفوذ ناقص ریشه","زیرگرفتگی (Undercut)","حفرهٔ گازی کروی","ترک عرضی در مرکز جوش"]'::jsonb, 1, 'SINGLE', null, 'زیرگرفتگی کاهش ضخامت در لبهٔ جوش است و نواری تیره در حاشیه ایجاد می‌کند.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر عیوب در فیلم', 3, 'لکهٔ تیرهٔ بزرگ، نامنظم و شدید در ناحیهٔ ریشه (فقط در یک نقطه) دیده می‌شود. محتمل‌ترین تفسیر چیست؟', '["ذرات تنگستن محبوس","ناهم‌ترازی ثابت لبه‌ها","سوختگی ریشه (Burn-through)","تخلخل خطی در ریشه"]'::jsonb, 2, 'SINGLE', null, 'ذوب بیش از حد ریشه باعث فرورفتگی و افت ضخامت و در نتیجه لکهٔ تیرهٔ شدید می‌شود.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر و نتیجهٔ ارزیابی', 3, 'یک خوشه تخلخل (CP) به قطر ۱۰ میلی‌متر دیده می‌شود و عیب دیگری وجود ندارد. نتیجهٔ ارزیابی طبق API 1104 چیست؟', '["مردود، چون هر خوشهٔ تخلخل مردود است","قابل قبول، ولی فیلم باید دوباره گرفته شود","مردود، چون قطر آن بیش از ۶ mm است","قابل قبول، چون قطر CP کمتر از ۱۳ mm است"]'::jsonb, 3, 'SINGLE', null, 'CP با قطر بیش از ۱/۲ in (۱۳ mm) یا مجموع طول CP بیش از ۱/۲ in در هر ۳۰۰ mm مردود است.', 'API 1104'),
  ('radiography_interpreter', 'تفسیر و نتیجهٔ ارزیابی', 3, 'سرباره کشیده (ESI) به طول ۶۰ میلی‌متر دیده می‌شود. نتیجه طبق API 1104 چیست؟', '["مردود است، چون طول ESI از ۵۰ میلی‌متر بیشتر است","قابل قبول است، چون کمتر از ۷۵ میلی‌متر است","قابل قبول است اگر عرض آن کمتر از ۳ میلی‌متر باشد","مردود است، ولی با تعمیر موضعی همیشه قابل قبول می‌شود"]'::jsonb, 0, 'SINGLE', null, 'ESI با طول بیش از ۲ in (۵۰ mm) مردود است.', 'API 1104'),
  ('radiography_interpreter', 'کیفیت فیلم', 2, 'محدودهٔ چگالی فیلم برای ناحیهٔ مورد تفسیر در کلاس B طبق ISO 17636-1 چقدر است؟', '["حدود ۰٫۵ تا ۱٫۰","حدود ۲٫۳ تا ۴٫۰","حدود ۴٫۵ تا ۶٫۰","حدود ۱٫۰ تا ۱٫۵"]'::jsonb, 1, 'SINGLE', null, 'در کلاس B چگالی نوری حداقل ۲٫۳ و معمولاً حداکثر ۴٫۰ است؛ کلاس A حداقل ۲٫۰.', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'کیفیت فیلم', 1, 'هدف از قرار دادن شاخص کیفیت تصویر (IQI سیمی) روی جوش چیست؟', '["اندازه‌گیری ضخامت دیواره لوله","تعیین نوع عیب با شکل سیم","اثبات حساسیت و کیفیت تصویر","کاهش زمان نوردهی مورد نیاز"]'::jsonb, 2, 'SINGLE', null, 'IQI نشان می‌دهد کوچک‌ترین سیم قابل رؤیت چقدر است و در نتیجه حساسیت تصویر کافی است.', 'ISO 19232-1 / ISO 17636-1'),
  ('radiography_interpreter', 'روش نوردهی', 2, 'در نوردهی پانورامیک (SWSI) با چشمهٔ مرکزی داخل لوله، IQI در کدام سمت قرار می‌گیرد؟', '["سمت فیلم (Film side)","روی پوشش سرب پشت فیلم","هیچ‌جا؛ IQI در این روش لازم نیست","سمت چشمه (Source side)"]'::jsonb, 3, 'SINGLE', null, 'در روش پانورامیک IQI سمت چشمه قرار می‌گیرد (حداقل ۳ عدد با فاصلهٔ زاویه‌ای مناسب).', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'روش نوردهی', 2, 'برای لوله با قطر خارجی ≤ ۱۰۰ میلی‌متر و ضخامت ≤ ۸ میلی‌متر کدام روش نوردهی متداول است؟', '["دیواره دوتایی - تصویر دوتایی (بیضوی)","دیواره تکی - تصویر تکی پانورامیک","دیواره دوتایی - تصویر تکی بدون جابه‌جایی چشمه","نوردهی از داخل با خزنده"]'::jsonb, 0, 'SINGLE', null, 'برای قطرهای کوچک روش بیضوی (DWDI) متداول است که هر دو بخش جوش را در یک تصویر نشان می‌دهد.', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'انتخاب چشمه', 3, 'برای رادیوگرافی جوش با ضخامت ۸ میلی‌متر و کیفیت کلاس B کدام چشمه مناسب‌تر است؟', '["Co-60 با انرژی بسیار بالا","X-ray یا Se-75 با حساسیت بهتر","Ir-192 در همین ضخامت","Cs-137 در ضخامت کم"]'::jsonb, 1, 'SINGLE', null, 'در ضخامت‌های کم، Ir-192 کنتراست مناسب نمی‌دهد؛ Se-75 یا X-ray حساسیت بهتری دارند.', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'ایمنی پرتو', 1, 'اگر فاصلهٔ فرد از چشمهٔ رادیوگرافی دو برابر شود، آهنگ دز تقریباً چند برابر می‌شود؟', '["نصف مقدار قبلی","دو برابر مقدار قبلی","یک‌چهارم مقدار قبلی","ثابت و مستقل از فاصله"]'::jsonb, 2, 'SINGLE', null, 'شدت پرتو با مجذور فاصله کاهش می‌یابد؛ دو برابر فاصله = یک‌چهارم دز.', 'قانون عکس مجذور فاصله'),
  ('radiography_interpreter', 'محاسبات رادیوگرافی', 2, 'اندازهٔ کانونی چشمه ۳ میلی‌متر، فاصلهٔ چشمه تا جسم ۵۰۰ میلی‌متر و فاصلهٔ جسم تا فیلم ۲۵ میلی‌متر است. ناواضحی هندسی (Ug) چند میلی‌متر است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"میلی‌متر","value":0.15,"tolPct":2}'::jsonb, 'Ug = f × t / d = 3 × 25 / 500 = 0.15 mm', 'ISO 17636-1 – ناواضحی هندسی'),
  ('radiography_interpreter', 'محاسبات رادیوگرافی', 2, 'نوردهی ۴ دقیقه در فاصلهٔ ۶۰ سانتی‌متر کافی بوده است. زمان نوردهی لازم در فاصلهٔ ۹۰ سانتی‌متر (شدت چشمه ثابت) چند دقیقه است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"دقیقه","value":9,"tolPct":2}'::jsonb, 't2 = t1 × (d2/d1)² = 4 × (90/60)² = 9 min', 'قانون عکس مجذور فاصله'),
  ('radiography_interpreter', 'شرایط تفسیر', 1, 'چرا تفسیر فیلم در اتاق نیمه‌تاریک و با نورگیر (Illuminator) با شدت قابل تنظیم انجام می‌شود؟', '["کاهش زمان نوردهی فیلم در کارگاه","کالیبره شدن خودکار دانسیتومتر","جلوگیری از افزایش چگالی فیلم","افزایش حساسیت دید و حذف بازتاب نور"]'::jsonb, 3, 'SINGLE', null, 'نور محیط و بازتاب کنتراست ظاهری تصویر را کاهش می‌دهد و تشخیص عیوب ظریف را دشوار می‌کند.', 'ISO 17636-1 (Radiographic testing of welded joints)'),
  ('radiography_interpreter', 'ثبت و گزارش', 2, 'پس از تعمیر یک جوش مردود، رادیوگرافی مجدد چگونه علامت‌گذاری و تفسیر می‌شود؟', '["علامت R1 و ارزیابی ناحیهٔ تعمیرشده","همان علامت اولیه و ثبت نکردن تعمیر","بازرسی چشمی ناحیه و فیلم نگرفتن","فیلم قدیمی و افزودن علامت جدید"]'::jsonb, 0, 'SINGLE', null, 'فیلم تعمیر با علامت مخصوص (R1، R2…) مشخص می‌شود تا سوابق تعمیر قابل ردیابی باشد.', 'API 1104')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
where not exists (select 1 from comp_mcq_questions e where e.job_role = v.job_role and e.stem_fa = v.stem_fa);
